UPDATE refresh_token
SET last_used_at = #{lastUsedAt}
WHERE id = #{id}

UPDATE refresh_token
SET revoked = 1,
    revoked_at = NOW(),
    revoke_reason = #{revokeReason}
WHERE id = #{id}

UPDATE refresh_token
SET revoked = 1,
    revoked_at = NOW(),
    revoke_reason = #{revokeReason}
WHERE uid = #{uid}
  AND revoked = 0
